    svg.appendChild(SVG("circle",{cx:px,cy:py,r:14,fill:"var(--panel2)",stroke:"var(--yellow)","stroke-width":2}));
    const t = SVG("text",{x:px,y:py+5,"text-anchor":"middle","font-size":12,fill:"var(--yellow)","font-weight":600});
    t.textContent = "p_"+i;
    svg.appendChild(t);
    // weight label outside
    const wx = cx + (R+30)*Math.cos(theta);
    const wy = cy + (R+30)*Math.sin(theta);
    const wt = SVG("text",{x:wx,y:wy+4,"text-anchor":"middle","font-size":11,fill:"var(--cyan)"});
    wt.textContent = "weight t_"+i+"^"+n;
    svg.appendChild(wt);
  }
  // formula at bottom
  const f = SVG("text",{x:W/2,y:H-40,"text-anchor":"middle","font-size":13,fill:"var(--ink)","font-style":"italic"});
  f.textContent = "∫ c_1(O(1))^"+n+" = Σ_i  t_i^"+n+" / Π_{j≠i} (t_j − t_i)  =  1";
  svg.appendChild(f);
  // result
  const res = SVG("text",{x:W/2,y:H-12,"text-anchor":"middle","font-size":11,fill:"var(--mute)"});
  res.textContent = "(verify: substitute any distinct values for the t_i — the rational sum collapses to 1)";
  svg.appendChild(res);
  let msg;
  if(n===1) msg = "$n=1$: two fixed points $p_0 = [1:0],\\,p_1=[0:1]$ on $\\mathbb{CP}^1$. Localisation: $\\frac{t_0}{t_1-t_0} + \\frac{t_1}{t_0-t_1} = 1$ — a one-line identity.";
  else if(n===2) msg = "$n=2$: three fixed points on $\\mathbb{CP}^2$. The localisation identity $\\sum_i t_i^2 / \\prod_{j\\ne i}(t_j-t_i) = 1$ holds for all choices of distinct $t_0,t_1,t_2$.";
  else if(n===3) msg = "$n=3$: four fixed points on $\\mathbb{CP}^3$. The polynomial identity $\\sum_i t_i^3 / \\prod_{j\\ne i}(t_j-t_i) = 1$ already requires partial-fraction work to check by hand.";
  else msg = "$n="+n+"$: "+(n+1)+" fixed points. Atiyah–Bott reduces an integral on $\\mathbb{CP}^"+n+"$ to a finite rational sum — all higher complexity is encoded in the $(n+1)\\times(n+1)$ Vandermonde-style denominator.";
  readout.innerHTML = msg;
  if(window.renderMathInElement){ try{ renderMathInElement(readout,{delimiters:[{left:"$",right:"$",display:false}],throwOnError:false}); }catch(e){} }
}
